import { Component, Element, Event, EventEmitter, h, Host, Listen, Prop, Watch } from '@stencil/core';
import { FlyoutPosition } from '../../types';

/**
 * @slot default - default slot for content of the flyout
 */
@Component({
  tag: 'groupui-flyout',
  styleUrl: 'flyout.scss',
  shadow: true,
})
export class Flyout {
  /**
   * toggles visibility
   */
  @Prop({ reflect: true, mutable: true }) visible: boolean;

  /**
   * position of the flyout
   */
  @Prop({ reflect: true }) readonly position: FlyoutPosition = 'right';

  /**
   * disables closing the flyout when clicked on backdrop
   */
  @Prop({ reflect: true }) readonly disableBackdropClose: boolean = false;

  /**
   * disables closing the flyout on escape key press
   */
  @Prop({ reflect: true }) readonly disableEscapeClose: boolean = false;

  @Element() host: HTMLElement;

  /**
   * is dispatched when flyout is closed
   */
  @Event({ bubbles: false }) groupuiFlyoutClose: EventEmitter<void>;

  private dialogRef: HTMLDialogElement;
  private contentRef: HTMLElement;

  componentDidLoad() {
    this.handleFocus();
    if (this.visible) {
      this.showDialog();
    }
  }

  @Listen('mousedown', { target: 'window' })
  onBackdropClick(event) {
    if (this.visible && !this.disableBackdropClose) {
      this.handleClickOnBackdrop(event);
    }
  }

  @Listen('keydown', { target: 'window' })
  onEscapeKeyDown(event: KeyboardEvent) {
    if (event.key === 'Escape') {
      if (this.disableEscapeClose) {
        event.preventDefault();
      } else if (this.visible) {
        event.preventDefault();
        this.visible = false;
      }
    }
  }

  @Watch('visible')
  onDisplayedChanged() {
    if (this.visible) {
      this.showDialog();
    } else {
      this.closeDialog();
    }
  }

  private showDialog() {
    this.dialogRef.showModal();
    this.handleFocus();
  }

  private closeDialog() {
    this.dialogRef?.classList.add('closing');
    setTimeout(() => {
      this.dialogRef?.classList.remove('closing');
      this.dialogRef?.close();
    }, 240);
  }

  private handleClickOnBackdrop = (event) => {
    const path = event.path || (event.composedPath && event.composedPath());

    if (this.isScrollbarClick(event)) {
      return;
    }

    if (!path.includes(this.contentRef)) {
      this.visible = null;
      this.groupuiFlyoutClose.emit();
    }
  };

  private isScrollbarClick(event) {
    const rect = this.contentRef.getBoundingClientRect();

    const isVerticalScrollbar = event.clientX >= rect.left + rect.width;

    if (isVerticalScrollbar) {
      return true;
    }
  }

  private handleFocus() {
    const autoFocusElements = this.getAutoFocusElements();
    if (autoFocusElements.length > 0) {
      (autoFocusElements[0] as HTMLElement)?.focus();
      return;
    }

    const focusableContent = this.getFocusableElements();
    if (focusableContent.length > 0) {
      (focusableContent[0] as HTMLElement)?.focus();
      return;
    }
    this.host.focus();
  }

  private getFocusableElements() {
    const childElements = (this.host as Node).childNodes;
    const childElementsArray = Array.from(childElements);
    return childElementsArray.filter((el) => el.nodeName !== '#text');
  }

  private getAutoFocusElements() {
    return this.host.querySelectorAll('[autofocus]');
  }

  render() {
    return (
      <Host tabindex={this.visible ? 0 : -1}>
        <dialog ref={(el) => (this.dialogRef = el)}>
          <div id="content" ref={(el) => (this.contentRef = el)}>
            <slot />
          </div>
        </dialog>
      </Host>
    );
  }
}
